                                                                                                                                                                                                                 
  CREATE TABLE "STS_PERMISSION"                                                                                                                                                                        
   (	"PERMISSION_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"PERMISSION_NAME" VARCHAR2(255),                                                                                                                                                                                
	"PARENT_ID" NUMBER(20,0),                                                                                                                                                                                       
	"PERMISSION_TYPE" NUMBER(20,0),                                                                                                                                                                                 
	"TENANT_ID" NUMBER(20,0),                                                                                                                                                                                       
	"REMARK" VARCHAR2(500),                                                                                                                                                                                         
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                           
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                             
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                               
	"APP_ID" NUMBER,                                                                                                                                                                                                
	"PAGE_ID" NUMBER,                                                                                                                                                                                               
	"PARENT_PAGE_ID" NUMBER(20,0),                                                                                                                                                                                  
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                              
	"SORT_NUM" NUMBER(10,0) DEFAULT 1,                                                                                                                                                                              
	 PRIMARY KEY ("PERMISSION_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                            
   ) ;                                                                                                                                                                                                           

